// scripts/build-ask-zugee-knowledge.mjs — run with `npm run knowledge:build`.
// Writes the chat assistant's knowledge (lib/chatbot/knowledge.js) to content/ask-zugee/*.md so it
// can be read and reviewed. The files are generated: edit the site data or the registry, then run
// this again. tests/chatbot.test.mjs fails if the committed files are out of date.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { knowledgeDocs } from "../lib/chatbot/knowledge.js";

export const GENERATED_HEADER =
  "<!-- Generated by `npm run knowledge:build` (scripts/build-ask-zugee-knowledge.mjs) from the site's data. Do not edit by hand. -->\n\n";

const dir = path.join(path.dirname(fileURLToPath(import.meta.url)), "..", "content", "ask-zugee");

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  fs.mkdirSync(dir, { recursive: true });
  for (const [name, body] of Object.entries(knowledgeDocs())) {
    fs.writeFileSync(path.join(dir, name), `${GENERATED_HEADER}${body}\n`);
    console.log(`Wrote content/ask-zugee/${name}`);
  }
}
